// Block (composition) — a chronological feed of actor activity.
// Avatar owns identity styling and Timeline the rail joining the entries; Stack arranges the groups.
import type { ReactNode, Ref } from "react";
import { Avatar } from "../components/Avatar";
import { Timeline, TimelineItem } from "../components/Timeline";
import { Stack } from "../layouts/Stack";
import { SkeletonList } from "./SkeletonList";
import "./ActivityFeed.css";

export interface ActivityFeedProps {
  /** Events to display in chronological order. */
  items: {
    id: string;
    actor?: string;
    avatarSrc?: string;
    action: ReactNode;
    timestamp?: string;
    /** A date group the event belongs to ("Today", "Yesterday"). Consecutive events that share one
     *  are listed under a single heading; with no group anywhere the feed is one list. */
    group?: string;
  }[];
  /** Renders skeleton placeholders while the feed is loading. */
  isLoading?: boolean;
  /** Message shown when there are no events. */
  emptyLabel?: string;
  className?: string;
  /** The feed's root: the list, or the section holding the groups when items carry `group`. */
  ref?: Ref<HTMLElement>;
}

export function ActivityFeed({
  items,
  isLoading,
  emptyLabel = "No activity yet",
  className,
  ref,
}: ActivityFeedProps) {
  if (isLoading) {
    return <SkeletonList rows={4} showAvatar className={className} />;
  }
  if (items.length === 0) {
    return (
      <p role="status" className={`sd-activityfeed__empty sd-type-caption-medium${className ? ` ${className}` : ""}`}>
        {emptyLabel}
      </p>
    );
  }
  const cls = className ? `sd-activityfeed ${className}` : "sd-activityfeed";
  // Content-presence fact the Figma master projects as its isGrouped axis.
  const isGrouped = items.some((item) => item.group);
  if (isGrouped) {
    // Consecutive events sharing a group form one run, in the order given.
    const groups: { label: string; items: ActivityFeedProps["items"] }[] = [];
    for (const item of items) {
      const label = item.group ?? "";
      const last = groups[groups.length - 1];
      if (last && last.label === label) last.items.push(item);
      else groups.push({ label, items: [item] });
    }
    // Two rungs over the list's own gap between groups, the list's gap under each heading
    // (token-contract.md § By relationship: stacked-units and heading-group).
    return (
      <Stack as="section" ref={ref} gap="x-large" aria-label="Activity" className={cls}>
        {groups.map((group, index) => (
          <Stack key={`${group.label}-${index}`} gap="medium" className="sd-activityfeed__group">
            {/* CONTRASTIVE: one rung below the entries it heads, as a collection's section-header. */}
            {group.label && (
              <>
                <h2 className="sd-activityfeed__group-label sd-type-label-small">{group.label}</h2>
              </>
            )}
            <Timeline className="sd-activityfeed__list">{group.items.map(renderItem)}</Timeline>
          </Stack>
        ))}
      </Stack>
    );
  }
  return (
    <Timeline ref={ref as Ref<HTMLOListElement>} aria-label="Activity" className={cls}>
      {items.map(renderItem)}
    </Timeline>
  );
}

function renderItem(item: ActivityFeedProps["items"][number]) {
  return (
    <TimelineItem
      key={item.id}
      className="sd-activityfeed__item"
      indicator={
        <Avatar src={item.avatarSrc} size="small" alt={item.actor ?? ""}>
          {item.actor?.charAt(0).toUpperCase()}
        </Avatar>
      }
    >
      <Stack gap="2x-small" className="sd-activityfeed__content">
        <span className="sd-activityfeed__event sd-type-body-medium">
          {/* The actor is emphasis INSIDE a sentence, so it takes the role's emphasized
              class rather than the UA's `bolder`: the UA resolves that
              to 700 everywhere while this scale's emphasis is 500 here (ADR-0027). */}
          {item.actor && <strong className="sd-type-body-medium-emphasized">{item.actor}</strong>}{" "}
          {item.action}
        </span>
        {item.timestamp && (
          <span className="sd-activityfeed__timestamp sd-type-caption-medium">
            {item.timestamp}
          </span>
        )}
      </Stack>
    </TimelineItem>
  );
}

/* ActivityFeed.css — .sd-activityfeed (Block)
   Arrangement only: Timeline owns the list, its spacing and the rail; Avatar owns identity styling. */
.sd-activityfeed {
  width: 100%;
  margin: 0;
  padding: 0;
  list-style: none;
}

.sd-activityfeed__group-label {
  margin: 0;
}

.sd-activityfeed__content {
  flex: 1;
  min-width: 0;
}

/* empty state — layout only (muted color inherits default; blocks own no color) */
.sd-activityfeed__empty {
  padding: var(--sd-space-large);
  text-align: center;
}
